"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

export type GaugeSpeed = "slow" | "normal" | "fast";

export interface GaugeTextProps {
  /** The number to count up to, e.g. 89 for "89x faster". */
  value: number;

  /** Appended directly to the number, no space (e.g. "x", "%"). */
  suffix?: string;

  /** Text shown after the gauge icon, e.g. "faster". */
  label: string;

  /** How fast the number counts up. */
  speed?: GaugeSpeed;

  /** Color used for the number and icon while counting. */
  color?: string;

  /** Class applied to the number + label once the count-up lands. */
  landedClassName?: string;

  /** Decimal places kept on the counted number. */
  decimals?: number;

  /** Overrides the count-up duration in seconds (derived from `speed` otherwise). */
  duration?: number;

  /** Hide the gauge icon and just count the number. */
  showIcon?: boolean;

  className?: string;
  numberClassName?: string;
  labelClassName?: string;
  iconClassName?: string;

  autoStart?: boolean;
  inView?: boolean;
  once?: boolean;

  onStart?: () => void;
  onComplete?: () => void;
}

export interface GaugeTextRef {
  play: () => void;
  reset: () => void;
}

const COUNT_DURATION: Record<GaugeSpeed, number> = {
  slow: 2.2,
  normal: 1.3,
  fast: 0.75,
};

function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

interface GaugeIconProps {
  color: string;
  landed: boolean;
  className?: string;
}

/**
 * The gauge glyph, fixed in place. It never moves or spins — only the
 * number and label around it change as the count-up plays.
 */
function GaugeIcon({ color, landed, className }: GaugeIconProps) {
  return (
    <span
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center",
        className
      )}
    >
      <svg viewBox="0 0 32 32" className="size-[0.72em]" fill="none">
        <path
          d="M 23.78 8.22 A 11 11 0 1 1 8.57 7.89"
          stroke="currentColor"
          strokeWidth="2.6"
          strokeLinecap="round"
          opacity={landed ? 0.35 : 0.9}
        />
        <path
          d="M 15.98 8.34
             C 15.9 6.8, 16.0 5.6, 16.99 5.11
             C 19.0 4.6, 22.3 5.6, 23.78 8.22"
          stroke="currentColor"
          strokeWidth="2.6"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity={landed ? 0.35 : 0.9}
        />
        <path
          d="M 11.6 10.9
             C 14.5 11.3, 19.2 13.0, 19.0 16.3
             C 18.8 19.0, 15.6 20.3, 13.3 18.7
             C 11.3 17.3, 10.6 14.0, 11.6 10.9 Z"
          stroke={color}
          strokeWidth="2.3"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </span>
  );
}

const GaugeText = forwardRef<GaugeTextRef, GaugeTextProps>(
  (
    {
      value,
      suffix = "x",
      label,
      speed = "normal",
      color = "hsl(var(--primary))",
      landedClassName = "text-foreground",
      decimals = 0,
      duration,
      showIcon = true,
      className,
      numberClassName,
      labelClassName,
      iconClassName,
      autoStart = true,
      inView = false,
      once = true,
      onStart,
      onComplete,
      ...props
    },
    ref
  ) => {
    const [display, setDisplay] = useState(0);
    const [landed, setLanded] = useState(false);

    const frame = useRef<number | null>(null);
    const hasPlayedRef = useRef(false);

    const countDuration = duration ?? COUNT_DURATION[speed];

    const play = useCallback(() => {
      if (frame.current) cancelAnimationFrame(frame.current);

      setLanded(false);
      onStart?.();

      const start = performance.now();

      const tick = (now: number) => {
        const elapsed = (now - start) / 1000;
        const t = Math.min(elapsed / countDuration, 1);
        const eased = easeOutExpo(t);

        setDisplay(value * eased);

        if (t < 1) {
          frame.current = requestAnimationFrame(tick);
        } else {
          setDisplay(value);
          setLanded(true);
          onComplete?.();
        }
      };

      frame.current = requestAnimationFrame(tick);
    }, [value, countDuration, onStart, onComplete]);

    const reset = useCallback(() => {
      if (frame.current) cancelAnimationFrame(frame.current);
      setDisplay(0);
      setLanded(false);
      hasPlayedRef.current = false;
    }, []);

    useImperativeHandle(ref, () => ({ play, reset }), [play, reset]);

    useEffect(() => {
      if (autoStart && !inView) {
        hasPlayedRef.current = true;
        play();
      }

      return () => {
        if (frame.current) cancelAnimationFrame(frame.current);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [autoStart, inView]);

    const handleViewportEnter = useCallback(() => {
      if (once && hasPlayedRef.current) return;
      hasPlayedRef.current = true;
      play();
    }, [once, play]);

    const formatted = useMemo(
      () => display.toFixed(decimals),
      [display, decimals]
    );

    return (
      <span
        className={cn(
          "inline-flex items-center gap-2 font-semibold",
          className
        )}
        {...props}
      >
        <GaugeTrigger inView={inView} once={once} onEnter={handleViewportEnter} />

        <span
          className={cn("tabular-nums", numberClassName)}
          style={{ color: landed ? undefined : color }}
        >
          {formatted}
          {suffix}
        </span>

        {showIcon && (
          <GaugeIcon color={color} landed={landed} className={iconClassName} />
        )}

        <span
          className={cn(landed ? landedClassName : undefined, labelClassName)}
          style={{ color: landed ? undefined : color }}
        >
          {label}
        </span>
      </span>
    );
  }
);

GaugeText.displayName = "GaugeText";

/**
 * Invisible helper that fires `onEnter` the first time the component
 * scrolls into view, when `inView` is enabled. Kept separate so the
 * main element can stay a plain `span` (no motion wrapper needed since
 * nothing here uses spring/tween animation anymore).
 */
function GaugeTrigger({
  inView,
  once,
  onEnter,
}: {
  inView: boolean;
  once: boolean;
  onEnter: () => void;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const firedRef = useRef(false);

  useEffect(() => {
    if (!inView || !ref.current) return;

    const node = ref.current;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        if (once && firedRef.current) return;
        firedRef.current = true;
        onEnter();
      },
      { rootMargin: "-10% 0px -10% 0px" }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, [inView, once, onEnter]);

  if (!inView) return null;

  return <span ref={ref} className="sr-only" aria-hidden="true" />;
}

export { GaugeText };
